FIX = Path(__file__).parent.parent / 'fixtures/hanjuku'
NAMES = ['デッドガン', 'ノリウツール', 'ブレイコウ', 'クースカン',
         'ブンシーン', 'ゼンマイン', 'ミックミー', 'ファイアーボイス']
FRAMES = {0: 'top', 3: 'row3', 4: 'row4', 6: 'row6', 7: 'bottom'}


def native(index=0):
    return parse(read_png(FIX / f'local-shop-list-{FRAMES[index]}.png'))


def memory(target=NAMES[-1], quantity=1):
    identity = {'game': 'hanjuku-speedrun', 'runtime_id': 'local-ui-calibration',
                'generation': 1, 'lease_id': 'synthetic'}
    return {'chapter': 9, 'month': '22-7', 'tick': 100, '_run_identity': identity,
            'recruit_roster': {'identity': identity, 'chapter': 9, 'month': '22-7',
                'tick': 90, 'complete': True, 'names': ['どうし'], 'wages': {'どうし': 0}},
            'shop': {'key': '22-7', 'items': [[target, quantity]], 'reserve': 0,
                     'bargain_listing_planned': True, 'bargain_planned': True, 'egg': 'done'}}


@pytest.mark.parametrize('origin,target,direction', [(0, 7, 'down'), (0, 3, 'down'),
    (3, 7, 'down'), (6, 0, 'up'), (7, 0, 'up'), (7, 4, 'up')])
def test_native_paths_have_three_taps_with_releases_and_fresh_feedback(origin, target, direction):
    screen = native(origin)
    before = deepcopy(screen)
    assert commands.menu_navigation_reading(screen)['cursor'] == [128, 39 + 16 * origin]
    actions = commands.merchant_list_batch(screen, NAMES[target])
    assert actions == taps(direction, 3)
    assert entry.observation_interval_ms(state(screen), actions) == 500
    assert screen == before
    assert entry.observation_interval_ms(state(screen), taps(direction, 4)) == 1500
    assert entry.observation_interval_ms(state(screen), [commands.pad(direction)]*3) == 1500
    for b in ('a', 'b'):
        assert entry.observation_interval_ms(state(screen), [commands.pad(b)]) == 1500


def test_native_seven_row_trip_needs_three_movement_observations_then_actual_a():
    mem = memory()
    for index, actions in [(0, taps('down', 3)), (3, taps('down', 3)), (6, [commands.pad('down')])]:
        screen = native(index)
        assert shop_step(screen, mem) == actions
        assert entry.observation_interval_ms(state(screen), actions) == 500
        assert mem['shop']['want'] == [NAMES[-1], 1, 22]
        assert mem['shop']['items'] == [[NAMES[-1], 1]]
        assert not mem['shop'].get('bought') and not mem['shop'].get('last_buy')
        assert not mem.get('card_bought_since_read')
    actions = shop_step(native(7), mem)
    assert actions == [commands.pad('a')]
    assert entry.observation_interval_ms(state(native(7)), actions) == 1500
    assert not mem['shop'].get('bought')  # opens a quantity editor; it is not payment


@pytest.mark.parametrize('landed', [0, 3, 6, 7])
def test_lost_or_extra_inputs_are_corrected_from_the_actual_next_cursor(landed):
    mem = memory(target=NAMES[4])
    assert shop_step(native(), mem) == taps('down', 3)
    actions = shop_step(native(landed), mem)
    expected = (taps('down', 3) if landed == 0 else [commands.pad('down')] if landed == 3
                else taps('up', 2) if landed == 6 else taps('up', 3))
    assert actions == expected
    assert not any(a.get('buttons') == ['a'] for a in actions)
    assert shop_step(native(4), mem) == [commands.pad('a')]


@pytest.mark.parametrize('change', ['missing_row', 'missing_after_cap', 'unknown_name',
    'missing_price', 'unknown_price', 'zero_price', 'price_gap', 'duplicate_row', 'duplicate_name',
    'duplicate_cell', 'wrong_pane', 'no_hand', 'wrong_hand', 'wrong_kind'])
def test_ambiguous_or_unpriced_paths_never_batch(change):
    screen = native()
    if change in ('missing_row', 'missing_after_cap'):
        screen.lines = [l for l in screen.lines if l.y != (55 if change == 'missing_row' else 119)]
    elif change == 'duplicate_row':
        screen.lines.append(next(l for l in screen.lines if l.y == 55))
    elif change == 'duplicate_name':
        line = next(l for l in screen.lines if l.y == 39)
        screen.lines = [replace(line, y=55) if l.y == 55 else l for l in screen.lines]
    elif change in ('no_hand', 'wrong_hand', 'wrong_kind'):
        if change == 'no_hand': screen.hand = None
        elif change == 'wrong_hand': screen.hand = (146, 33, 166, 46)
        else: screen.kind = 'text'
    else:
        line = next(l for l in screen.lines if l.y == 55)
        if change == 'duplicate_cell': cells = line.cells + ((128, 'ノ'),)
        elif change == 'wrong_pane': cells = tuple((x-8 if 128 <= x < 192 else x, ch) for x, ch in line.cells)
        elif change == 'price_gap': cells = tuple((200 if x == 208 else x, ch) for x, ch in line.cells)
        elif change == 'missing_price': cells = tuple((x, ch) for x, ch in line.cells if x < 192)
        else:
            x = 128 if change == 'unknown_name' else 208
            char = '0' if change == 'zero_price' else UNKNOWN
            cells = tuple((cx, char if cx == x else ch) for cx, ch in line.cells)
        screen.lines = [replace(l, cells=cells) if l.y == 55 else l for l in screen.lines]
    assert commands.merchant_list_batch(screen, NAMES[-1]) is None


